"grammar": [
{"pattern":"～ば","usage":"nếu...(điều kiện giả định)","example":"会員になれば、割引を受けることができます。","example_reading":"かいいんになれば、わりびきをうけることができます。","example_meaning":"Nếu trở thành hội viên thì có thể được giảm giá."},
{"pattern":"～てしまう","usage":"làm xong hoàn toàn/lỡ làm gì (tiếc nuối)","example":"セール中についたくさん買ってしまいました。","example_reading":"せーるちゅうについたくさんかってしまいました。","example_meaning":"Trong lúc sale tôi lỡ mua quá nhiều đồ."},
{"pattern":"～ようになる","usage":"trở nên có thể/dần dần trở thành","example":"ネットで買い物ができるようになって、生活がとても便利になりました。","example_reading":"ねっとでかいものができるようになって、せいかつがとてもべんりになりました。","example_meaning":"Từ khi có thể mua sắm qua mạng, cuộc sống trở nên rất tiện lợi."},
{"pattern":"～かどうか","usage":"có...hay không","example":"このサイズが合うかどうか、試着してから決めます。","example_reading":"このさいずがあうかどうか、しちゃくしてからきめます。","example_meaning":"Tôi sẽ quyết định sau khi mặc thử xem cỡ này có vừa hay không."},
{"pattern":"～次第","usage":"ngay khi, tùy vào","example":"商品が届き次第、メールでお知らせします。","example_reading":"しょうひんがとどきしだい、めーるでおしらせします。","example_meaning":"Ngay khi hàng đến, chúng tôi sẽ thông báo qua email."},
{"pattern":"～わりに","usage":"so với...thì(khác thường)","example":"この店は値段の割に、品質がとてもいいです。","example_reading":"このみせはねだんのわりに、ひんしつがとてもいいです。","example_meaning":"So với giá thì chất lượng của cửa hàng này rất tốt."},
{"pattern":"～際に","usage":"khi, vào lúc (trang trọng)","example":"ご購入の際に、会員カードをご提示ください。","example_reading":"ごこうにゅうのさいに、かいいんかーどをごていじください。","example_meaning":"Khi mua hàng, xin vui lòng xuất trình thẻ hội viên."},
{"pattern":"～たびに","usage":"mỗi lần...","example":"このスーパーに来るたびに、新しい商品が増えている気がします。","example_reading":"このすーぱーにくるたびに、あたらしいしょうひんがふえているきがします。","example_meaning":"Mỗi lần đến siêu thị này, tôi cảm thấy sản phẩm mới lại tăng thêm."},
{"pattern":"～たらいい","usage":"nếu...thì tốt","example":"もう少し安かったらいいのに。","example_reading":"もうすこしやすかったらいいのに。","example_meaning":"Giá rẻ hơn chút nữa thì tốt biết mấy."},
{"pattern":"～のに","usage":"vậy mà, mặc dù","example":"安いのに品質がいいです。","example_reading":"やすいのにひんしつがいいです。","example_meaning":"Rẻ vậy mà chất lượng lại tốt."},
{"pattern":"～てもかまわない","usage":"làm cũng không sao","example":"現金でなくてもかまいません。","example_reading":"げんきんでなくてもかまいません。","example_meaning":"Không phải tiền mặt cũng không sao."},
{"pattern":"～ことはない","usage":"không cần phải","example":"慌てて買うことはありません。","example_reading":"あわててかうことはありません。","example_meaning":"Không cần vội mua đâu."},
{"pattern":"～ば～ほど","usage":"càng...càng","example":"安ければ安いほど売れます。","example_reading":"やすければやすいほどうれます。","example_meaning":"Càng rẻ thì càng bán chạy."},
{"pattern":"～に限る","usage":"tốt nhất là","example":"買い物は午前中に限ります。","example_reading":"かいものはごぜんちゅうにかぎります。","example_meaning":"Mua sắm thì tốt nhất là buổi sáng."},
{"pattern":"～だけあって","usage":"xứng đáng là, đúng là","example":"高いだけあって長持ちします。","example_reading":"たかいだけあってながもちします。","example_meaning":"Đắt có khác, dùng rất bền."},
{"pattern":"～に決まっている","usage":"chắc chắn là","example":"セールなら混むに決まっています。","example_reading":"せーるならこむにきまっています。","example_meaning":"Sale thì chắc chắn là đông rồi."},
{"pattern":"～ものなら","usage":"nếu có thể thì","example":"返品できるものならしたいです。","example_reading":"へんぴんできるものならしたいです。","example_meaning":"Nếu trả lại được thì tôi muốn trả."},
{"pattern":"～てまで","usage":"đến mức phải","example":"借金してまで買いたくありません。","example_reading":"しゃっきんしてまでかいたくありません。","example_meaning":"Tôi không muốn mua đến mức phải vay nợ."},
{"pattern":"～ついでに","usage":"nhân tiện","example":"買い物のついでに郵便局へ寄ります。","example_reading":"かいもののついでにゆうびんきょくへよります。","example_meaning":"Nhân tiện đi mua sắm tôi ghé bưu điện."}
]
